(function(){var D=document;if(D.getElementById("affirmations-local"))return;var e=D.createElement("script");e.type="application/json";e.id="affirmations-local";e.textContent="[\"आज सब कुछ करना ज़रूरी नहीं है। बस अगला छोटा काम काफ़ी है।\", \"थकना हार जाना नहीं है। तुम थकी हो, क्योंकि तुम हर दिन डटी रहती हो।\", \"बर्तन इंतज़ार कर सकते हैं। तुम्हें पाँच मिनट बैठने का पूरा हक़ है।\", \"रात के खाने में कॉर्नफ़्लेक्स भी परिवार का पेट भरना ही है।\", \"आराम कमाना नहीं पड़ता। तुम अभी इसी वक़्त आराम कर सकती हो।\", \"कुछ दिनों में जीत यही होती है कि सब सोने के वक़्त तक ठीक-ठाक पहुँच गए। यह सच्ची जीत है।\", \"तुम जितना करती हो, उतना कोई नहीं देखता। मैं देखती हूँ।\", \"बिखरा हुआ घर और प्यार में पले बच्चे। यह अच्छा सौदा है।\", \"मुश्किल दिन में तुम्हारी पूरी कोशिश अलग दिखती है, फिर भी वह गिनी जाती है।\", \"एक गहरी साँस। कंधे ढीले छोड़ दो। तुम अच्छा कर रही हो।\", \"आज उम्मीदें थोड़ी कम रखना ठीक है। किसी और दिन फिर बढ़ा लेना।\", \"मदद माँगना हिम्मत की बात है, कमज़ोरी की नहीं।\", \"एक और काम को ना कहने का तुम्हें हक़ है।\", \"अगर आज तुम्हें अकेलापन लगा, तो ऐसा महसूस करने वाली तुम अकेली माँ नहीं हो। हम बहुत सारी हैं।\", \"तुम ऐसी सहेली की हक़दार हो जो तुम्हारा हाल पूछे और जवाब का इंतज़ार करे।\", \"पहले ख़ुद बात शुरू करना ठीक है। ज़्यादातर माँएँ यही चाहती हैं कि कोई पहल करे।\", \"अनदेखा महसूस करने का मतलब यह नहीं कि तुम मायने नहीं रखतीं। तुम बहुत मायने रखती हो।\", \"तुम्हारी भावनाएँ समझ में आती हैं। तुम ज़रूरत से ज़्यादा नहीं हो।\", \"यहाँ तुम्हें अपना मुश्किल दिन समझाने की ज़रूरत नहीं। हम समझते हैं।\", \"किसी दूसरी माँ को \\\"मेरे साथ भी\\\" लिखा एक मैसेज पूरा दिन बदल सकता है।\", \"दूध पिलाना, कपड़े बदलना, झुलाना, और फिर वही। यह असली काम है, भले ही बस बैठे रहने जैसा लगे।\", \"तुम और तुम्हारा बच्चा अभी एक-दूसरे को जान रहे हो। कोई जल्दी नहीं है।\", \"नवजात शिशु के साथ दिन लंबे होते हैं। यह दौर हमेशा नहीं रहेगा।\", \"अगर आज तुमने बस एक नन्ही-सी जान का पेट भरा और उसे गर्म रखा, तो तुमने बहुत बड़ा काम किया।\", \"तुम्हें जल्दी पहले जैसा होने की ज़रूरत नहीं। तुम जहाँ हो, वहीं रह सकती हो।\", \"बच्चे को चाहे जैसे भी दूध मिले, तुम उसका ख़याल रख रही हो। यही मायने रखता है।\", \"नींद कम और प्यार भरपूर, दोनों एक साथ हो सकते हैं।\", \"बच्चे को गोद में लो और घर के काम छोड़ दो। घर कहीं नहीं जा रहा।\", \"दुकान में बच्चे का रोना-मचलना तुम्हें बुरी माँ नहीं बनाता। इसका मतलब बस इतना है कि तुम्हारा बच्चा छोटा है।\", \"छोटे बच्चे हदें इसलिए परखते हैं क्योंकि तुम्हारे साथ वे सुरक्षित महसूस करते हैं।\", \"आज तुम कल से एक मिनट ज़्यादा शांत रहीं। यह गिना जाता है।\", \"अगर ग़ुस्सा आ गया, तो एक झप्पी और एक \\\"सॉरी\\\" बहुत कुछ ठीक कर देते हैं। और इससे बच्चे कुछ अच्छा भी सीखते हैं।\", \"चिपचिपे हाथ, ऊँची आवाज़ें, बड़ी भावनाएँ। तुम एक पूरा इंसान बड़ा कर रही हो।\", \"इस घंटे का पाँचवाँ \\\"क्यों?\\\" एक नन्हा दिमाग़ है जो बढ़ रहा है।\", \"ख़ुशनुमा याद बनाने के लिए परफ़ेक्ट दिन की ज़रूरत नहीं।\", \"ज़ोर से बंद हुआ दरवाज़ा कहानी का अंत नहीं है। रोशनी जलाए रखो।\", \"तुम्हारा किशोर बच्चा शायद कहे नहीं, पर तुम्हारा हर दिन साथ होना उसके लिए मायने रखता है।\", \"घर में शांत रहने वाली बनना मेहनत का काम है। और तुम यह कर रही हो।\", \"कुछ सबसे अच्छी बातें गाड़ी में होती हैं। बस चलती रहो।\", \"वे बड़े होने के लिए दूर जाते हैं, तुम्हें पीछे छोड़ने के लिए नहीं।\", \"तुम्हें हर सवाल का जवाब पता होना ज़रूरी नहीं। सुनना ही बहुत बड़ी बात है।\", \"बड़े बच्चों को अब भी तुम्हारी ज़रूरत है, बस चुपचाप तरीक़ों से।\", \"सब कुछ अकेले सँभालने में ऐसी ताक़त लगती है जो ज़्यादातर लोग कभी देख नहीं पाते।\", \"तुम अपने बच्चे के लिए काफ़ी अच्छी माँ हो। हमेशा से थीं।\", \"दो हाथ, सौ काम। ख़ुद पर थोड़ी नरमी रखो।\", \"तुम्हारे बच्चे तुम्हें देखकर सीख रहे हैं कि एक मज़बूत और प्यार करने वाला इंसान कैसा होता है।\", \"थोड़ा रुकना ज़िम्मेदारी छोड़ना नहीं है। इसी से तुम आगे चल पाती हो।\", \"कोई हिसाब नहीं रख रहा। प्यार और साथ होना, यही मायने रखता है।\", \"दुख और प्यार एक ही जगह से आते हैं। किसी की याद आना बताता है कि तुमने कितना प्यार किया।\", \"शोक का कोई सही समय तय नहीं होता। जितना वक़्त चाहिए, उतना लो।\", \"मुश्किल बरसियों पर ख़ुद के साथ उतनी ही नरमी रखो जितनी किसी सहेली के साथ रखतीं।\", \"तुम उदासी लिए हुए भी अपने बच्चों के साथ हँस सकती हो। दोनों सच हैं।\", \"अगर तुमने गर्भ या बच्चा खोया है, तो वह दुख सच्चा है, और तुम्हारा प्यार भी।\", \"कुछ दिन दुख चुप रहता है और कुछ दिन शोर मचाता है। दोनों ठीक हैं।\", \"पैसे की कमी का मतलब प्यार की कमी नहीं है।\", \"तुम्हारे बच्चों को ख़रीदी चीज़ों से ज़्यादा तुम्हारे साथ बिताया वक़्त याद रहेगा।\", \"बिलों के लिए मदद के बारे में पूछना समझदारी है, शर्म की बात नहीं। मदद इसीलिए तो है।\", \"पार्क में बिना पैसे की एक दोपहर हफ़्ते का सबसे अच्छा दिन बन सकती है।\", \"तुमने पैसों को एक हफ़्ता और खींच लिया। यह सच में हुनर है।\", \"पैसों की चिंता थका देती है। तुम बहुत कुछ उठाए हुए हो, और फिर भी डटी हो।\", \"आज तुमने एक गिलास पानी पिया। वहीं से शुरू करो।\", \"सब घर से निकल गए। शायद जूते मेल नहीं खा रहे थे। फिर भी जीत है।\", \"तुमने वह फ़ोन कर ही दिया जिससे तुम घबरा रही थीं। यह हिम्मत थी।\", \"आज तुम हँसीं। इसे सँभालकर रखो।\", \"गर्म खाना, साफ़ कपड़े, सोते वक़्त की कहानी। छोटी-छोटी बातें मिलकर बचपन बनाती हैं।\", \"आज तुमने किसी के साथ अच्छा बर्ताव किया, भले ही वह तुम ख़ुद थीं।\", \"परफ़ेक्शन नहीं, आगे बढ़ना। आज तुम आगे बढ़ीं।\", \"तुमने लिस्ट का एक काम पूरा किया। कुछ न होने से एक ज़्यादा।\", \"तुम अच्छी माँ हो। तुम्हें इसकी फ़िक्र है, यही दिखाता है कि तुम कितनी परवाह करती हो।\", \"दिन भर में जितना कर पाती हो, तुम उससे कहीं बढ़कर हो।\", \"तुम्हारे बच्चों को परफ़ेक्ट माँ नहीं चाहिए। उन्हें तुम चाहिए, और तुम उनके पास हो।\", \"ख़ुद के साथ उतना ही धीरज रखो जितना अपने बच्चों के साथ रखती हो।\", \"तुम्हें अपनी जगह लेने, चीज़ें चाहने और अपने सपने रखने का हक़ है।\", \"एक ग़लती प्यार को मिटा नहीं देती। कल नई शुरुआत है।\", \"तुम किसी की पूरी दुनिया हो, और तुम अपने आप में भी एक इंसान हो।\", \"हर पल अच्छा न लगना ठीक है। तुम फिर भी अपने बच्चों से पूरे दिल से प्यार कर सकती हो।\", \"माँ बनने का कोई एक सही तरीक़ा नहीं है। तुम्हारा तरीक़ा भी सही है।\", \"वृक्षासन की तरह, डगमगाना ठीक है। तुम फिर से संतुलन पा सकती हो।\", \"ताड़ासन की तरह पैर जमाओ। तुम जितना महसूस करती हो, उससे ज़्यादा मज़बूती से खड़ी हो।\", \"वीरभद्रासन दो: मज़बूत पैर, खुली बाँहें। यही तुम हो, इस हफ़्ते का सामना करती हुई।\", \"चार गिनकर साँस लो, चार गिनकर छोड़ो। तुम यहीं हो, और अच्छा कर रही हो।\", \"तारे की तरह खुलकर फैलो। तुम्हें जगह लेने का हक़ है।\", \"चौड़ी, नीची बैठक में टिके रहना मुश्किल है। लंबा दिन भी ऐसा ही है। और तुम टिकी हुई हो।\", \"तुम अर्धचंद्र की तरह झुककर भी खड़ी रह सकती हो।\", \"अभी पैरों की उँगलियाँ छूना ज़रूरी नहीं। हर थोड़ा-सा खिंचाव भी गिना जाता है।\", \"त्रिकोणासन: एक हाथ नीचे, एक हाथ ऊपर। ज़मीन से जुड़ी रहो और ऊपर की ओर खिंचती रहो।\", \"देर हो गई है। जो आज नहीं हुआ, वह कल तक रुक सकता है।\", \"इस वक़्त बच्चे के साथ जाग रही हो? इस पल बहुत-सी माँएँ तुम्हारे साथ जाग रही हैं।\", \"घर शांत है। यह पल तुम्हारा है। साँस लो।\", \"तुमने आज का दिन पार कर लिया। आज को बस इतना ही चाहिए था।\", \"अगर आज रात मन बेचैन है, तो सब लिख लो और उसे सुबह तक रुकने दो।\", \"आँखों को आराम दो। कल फिर से शुरू कर सकती हो।\", \"त्योहार ख़ुशी के साथ-साथ मुश्किल भी हो सकते हैं। यह मौसम तुम्हें जैसा भी लगे, ठीक है।\", \"खाने की मेज़ का परफ़ेक्ट होना ज़रूरी नहीं। उसके आसपास बैठे लोग ही मायने रखते हैं।\", \"अगर इस साल किसी की कमी खल रही है, तो अपने दिल के साथ नरमी रखो।\", \"शुक्रिया माँ, हर खाने, हर सफ़र और हर झप्पी के लिए।\", \"मेहमान बुलाना, पकवान बनाना या हर वक़्त मुस्कुराना ज़रूरी नहीं। सादा त्योहार भी त्योहार ही है।\", \"इस साल तुम्हारे बच्चों को मिलने वाला सबसे अच्छा तोहफ़ा तुम्हारे साथ बिताया वक़्त है।\", \"छोटा-सा जश्न भी प्यार से भरा होता है। उसे ख़ास बनाने के लिए ज़्यादा पैसे नहीं चाहिए।\", \"ठंडे दिन, गर्म झप्पियाँ। तुम अपने घर की गर्माहट हो।\", \"त्योहारों की कुछ भागदौड़ छोड़ देना ठीक है। सुकून भी एक तोहफ़ा है।\", \"अगर इस साल यह मौसम भारी लग रहा है, तो तुम अकेली नहीं हो। एक-एक दिन करके चलो।\"]";D.body.appendChild(e)})();
